meta.checks:
local red1 = { userId = 1, team = "Red" }
local red2 = { userId = 2, team = "Red" }
local blue = { userId = 3, team = "Blue" }
local ffa = { userId = 4 }
local strict = { friendlyFire = false, selfDamage = false }
local loose = { friendlyFire = true, selfDamage = true }
assert(candidate(red1, blue, strict, 0) == true)
assert(candidate(red1, red2, strict, 0) == false)
assert(candidate(red1, red2, loose, 0) == true)
assert(candidate(red1, red1, strict, 0) == false and candidate(red1, red1, loose, 0) == true)
assert(candidate(ffa, { userId = 5 }, strict, 0) == true)
local fresh = { userId = 6, team = "Blue", protectedUntil = 10 }
assert(candidate(red1, fresh, loose, 9.9) == false)
assert(candidate(red1, fresh, loose, 10) == true)
assert(candidate({ userId = 0 }, blue, loose, 0) == false and candidate({ userId = 1.5 }, blue, loose, 0) == false)
assert(candidate(red1, blue, { friendlyFire = true }, 0) == false and candidate(red1, blue, loose, 0/0) == false)
assert(candidate(red1, { userId = 3, team = 5 }, loose, 0) == false)
